import "@once-ui-system/core/css/styles.css";
import "@once-ui-system/core/css/tokens.css";
import "./fonts.css";

import type { Metadata } from "next";
import { Column, Flex } from "@once-ui-system/core";
import { Providers } from "./providers";

export const metadata: Metadata = { title: "Benchmark" };

export default function RootLayout({ children }: { children: React.ReactNode }) {
  return (
    <Flex as="html" lang="en" suppressHydrationWarning>
      <Column as="body" background="page" fillWidth margin="0" padding="0" minHeight="100vh">
        <Providers>{children}</Providers>
      </Column>
    </Flex>
  );
}

/** @type {import('next').NextConfig} */
const nextConfig = {
  // Identical across arms. Telemetry/lint are disabled via env in the runner.
  reactStrictMode: true,
};

export default nextConfig;

"use client";

// Standard Once UI provider stack (mirrors the official Next.js starter):
// theme, Next-aware links/images, chart theme, toasts, icons.
import { DataThemeProvider, IconProvider, ThemeProvider, ToastProvider } from "@once-ui-system/core";
import { LayoutProvider } from "@once-ui-system/core/next";

export function Providers({ children }: { children: React.ReactNode }) {
  return (
    <ThemeProvider>
      <LayoutProvider>
        <DataThemeProvider>
          <ToastProvider>
            <IconProvider>{children}</IconProvider>
          </ToastProvider>
        </DataThemeProvider>
      </LayoutProvider>
    </ThemeProvider>
  );
}

/* System font stack, identical in every arm (no network font fetch at build). */
:root {
  --font-heading: ui-sans-serif, system-ui, sans-serif;
  --font-body: ui-sans-serif, system-ui, sans-serif;
  --font-label: ui-sans-serif, system-ui, sans-serif;
  --font-code: ui-monospace, monospace;
}

// Placeholder — the runner overwrites this file with the generated page.
export default function Page() {
  return null;
}

import "@once-ui-system/core/css/styles.css";
import "@once-ui-system/core/css/tokens.css";

import { Column, Row, ThemeInit } from "@once-ui-system/core";
import type { Metadata } from "next";
import { Geist, Geist_Mono } from "next/font/google";
import { Providers } from "../components/Providers";
import { app } from "../resources/app";
import { dataStyle, style } from "../resources/once-ui.config";

// Once UI reads these four variables; one family for heading, body and label.
const sans = Geist({ variable: "--font-heading", subsets: ["latin"], display: "swap" });
const body = Geist({ variable: "--font-body", subsets: ["latin"], display: "swap" });
const label = Geist({ variable: "--font-label", subsets: ["latin"], display: "swap" });
const code = Geist_Mono({ variable: "--font-code", subsets: ["latin"], display: "swap" });

export const metadata: Metadata = {
  title: { default: app.name, template: `%s · ${app.name}` },
  description: app.description,
};

export default function RootLayout({ children }: { children: React.ReactNode }) {
  return (
    <Row
      as="html"
      lang="en"
      suppressHydrationWarning
      className={[sans.variable, body.variable, label.variable, code.variable].join(" ")}
    >
      <head>
        {/* Sets data-theme and the scheme before first paint. */}
        <ThemeInit config={style} dataStyle={dataStyle} />
      </head>
      <Providers>
        <Column as="body" background="page" fillWidth margin="0" padding="0" minHeight="100vh">
          {children}
        </Column>
      </Providers>
    </Row>
  );
}

import type { OnceUIDataStyleConfig, OnceUIStyleConfig } from "@once-ui-system/core";

export const style: OnceUIStyleConfig = {
  // "dark" or "light" here locks the theme and the top-bar switch stops working.
  // Keep "system" and pick what a first visit sees with defaultTheme.
  theme: "system",
  defaultTheme: "dark", // dark | light | system
  neutral: "gray", // sand | gray | slate | rose | mint | dusk
  brand: "blue", // blue | indigo | violet | magenta | pink | red | orange | yellow | moss | green | emerald | aqua | cyan
  accent: "indigo", // same names as brand
  solid: "contrast", // color | contrast | inverse
  solidStyle: "flat", // flat | plastic
  border: "playful", // rounded | playful | conservative
  surface: "filled", // filled | translucent
  transition: "all", // all | micro | macro
  scaling: "100", // 90 | 95 | 100 | 105 | 110
};

export const dataStyle: OnceUIDataStyleConfig = {
  variant: "gradient", // flat | gradient | outline
  mode: "categorical", // categorical | divergent | sequential
  height: 24,
  axis: { stroke: "var(--neutral-alpha-weak)" },
  tick: { fill: "var(--neutral-on-background-weak)", fontSize: 11, line: false },
};

"use client";

import {
  DataThemeProvider,
  IconProvider,
  ThemeProvider,
  ToastProvider,
} from "@once-ui-system/core";
import { LayoutProvider } from "@once-ui-system/core/next";
import { dataStyle, style } from "../resources/once-ui.config";

// LayoutProvider from /next, not the package root: only the /next one routes
// links and images through next/link and next/image.
export function Providers({ children }: { children: React.ReactNode }) {
  return (
    <LayoutProvider>
      <ThemeProvider {...style}>
        <DataThemeProvider {...dataStyle}>
          <ToastProvider>
            <IconProvider>{children}</IconProvider>
          </ToastProvider>
        </DataThemeProvider>
      </ThemeProvider>
    </LayoutProvider>
  );
}

"use client";

import {
  Breadcrumbs,
  Button,
  Column,
  Drawer,
  Icon,
  IconButton,
  Kbar,
  type KbarItem,
  Nav,
  NavGroup,
  NavItem,
  Option,
  Row,
  selectNavHref,
  Text,
  ThemeSwitcher,
  User,
} from "@once-ui-system/core";
import { usePathname } from "next/navigation";
import { useState } from "react";
import { app, nav, navLinks, user } from "../resources/app";

/**
 * The signed-in frame: top bar, sidebar and a raised content panel. Only the
 * panel scrolls; the bar and sidebar stay put. Below `s` the sidebar hides and
 * the menu button opens the same nav in a left drawer. Edit src/resources/app.ts
 * for the name, user and nav; edit this file only to change the frame itself.
 */
export function AppShell({ children }: { children: React.ReactNode }) {
  const pathname = usePathname() ?? "";
  const current = selectNavHref(
    pathname,
    navLinks.map((link) => link.href),
  );
  // The drawer is open for the path it was opened on, so following a link in it
  // closes it with the navigation.
  const [menuPath, setMenuPath] = useState<string | null>(null);
  const [searchOpen, setSearchOpen] = useState(false);

  const group = nav.find(
    (entry) => "items" in entry && entry.items.some((l) => l.href === current),
  );
  const page = navLinks.find((link) => link.href === current);
  const crumbs = [
    { label: app.name, href: navLinks[0].href },
    ...(group ? [{ label: group.label }] : []),
    ...(page ? [{ label: page.label }] : []),
  ];

  const commands: KbarItem[] = navLinks.map((link) => ({
    id: link.href,
    name: link.label,
    section: "Pages",
    shortcut: [],
    keywords: link.label.toLowerCase(),
    href: link.href,
    icon: link.icon,
  }));

  const avatar = { value: initials(user.name), src: user.avatar || undefined };
  const account = (
    <Column padding="4" gap="2" minWidth="12rem">
      <Column paddingX="12" paddingY="8">
        <Text textVariant="label-strong-s">{user.name}</Text>
        <Text textVariant="body-default-xs" onBackground="neutral-weak">
          {user.email}
        </Text>
      </Column>
      <Option
        value="sign-out"
        label="Sign out"
        prefix={<Icon name="logout" size="s" onBackground="neutral-weak" />}
      />
    </Column>
  );

  const sideNav = (
    <Nav fill paddingX="8" density="compact" aria-label="Main">
      {nav.map((entry) =>
        "items" in entry ? (
          <NavGroup
            key={entry.label}
            label={entry.label}
            icon={entry.icon}
            defaultOpen={entry.items.some((l) => l.href === current)}
          >
            {entry.items.map((link) => (
              <NavItem
                key={link.href}
                href={link.href}
                label={link.label}
                selected={link.href === current}
              />
            ))}
          </NavGroup>
        ) : (
          <NavItem
            key={entry.href}
            href={entry.href}
            icon={entry.icon}
            label={entry.label}
            selected={entry.href === current}
          />
        ),
      )}
    </Nav>
  );

  return (
    <Column fill flex={1}>
      <Row as="header" height="56" fillWidth vertical="center" paddingX="16" gap="12">
        <Row hide s={{ hide: false }}>
          <IconButton
            icon="menu"
            variant="tertiary"
            tooltip="Menu"
            aria-expanded={menuPath === pathname}
            onClick={() => setMenuPath(pathname)}
          />
        </Row>
        <Row minWidth="16rem" s={{ minWidth: 0 }}>
          <Text textVariant="heading-strong-s">{app.name}</Text>
        </Row>
        <Row flex={1} s={{ hide: true }}>
          <Breadcrumbs items={crumbs} />
        </Row>
        <Row s={{ flex: 1 }} />
        <Button
          size="s"
          variant="secondary"
          prefixIcon="search"
          label="Search"
          onClick={() => setSearchOpen(true)}
        />
        <ThemeSwitcher collapsed direction="column" />
        {/* Name and email beside the avatar on desktop; the avatar alone on phones. */}
        <Row s={{ hide: true }}>
          <User
            name={user.name}
            subline={user.email}
            placement="bottom-end"
            avatarProps={avatar}
            dropdown={account}
          />
        </Row>
        <Row hide s={{ hide: false }}>
          <User placement="bottom-end" avatarProps={avatar} dropdown={account} />
        </Row>
      </Row>

      <Row fill paddingX="8">
        <Column s={{ hide: true }} maxWidth="16rem" fitHeight position="sticky" top="56">
          {sideNav}
        </Column>
        <Row fill horizontal="center" topRadius="l" overflow="hidden">
          <Row
            as="main"
            height="below-header"
            overflowY="auto"
            topRadius="l"
            horizontal="center"
            fillWidth
            background="surface"
            border
          >
            <Column maxWidth="xl" paddingX="24" paddingY="32" fitHeight>
              {children}
            </Column>
          </Row>
        </Row>
      </Row>

      <Drawer
        open={menuPath === pathname}
        onClose={() => setMenuPath(null)}
        side="left"
        size="s"
        title="Menu"
        flush
      >
        <Column paddingTop="64" paddingBottom="16">
          {sideNav}
        </Column>
      </Drawer>
      <Kbar items={commands} open={searchOpen} onOpenChange={setSearchOpen} />
    </Column>
  );
}

const initials = (name: string) =>
  name
    .split(" ")
    .map((part) => part.charAt(0))
    .join("")
    .slice(0, 2)
    .toUpperCase();

import type { IconName } from "@once-ui-system/core";

// Everything the shell shows that is about your product. Edit this file; the
// shell, the breadcrumb and the command palette all read from it.

export const app = {
  name: "Acme",
  // Page titles read "<Page> · Acme"; see `metadata` in src/app/layout.tsx.
  description: "The Acme app",
};

export const user = {
  name: "Jane Doe",
  email: "jane@example.com",
  avatar: "", // an image URL, or "" for initials
};

export type NavLink = { href: string; label: string; icon?: IconName };
export type NavEntry = NavLink | { label: string; icon: IconName; items: NavLink[] };

// Top-level links take an icon; links inside a group take none (the group's rail
// carries the hierarchy). Every href needs a page under src/app/(app)/.
export const nav: NavEntry[] = [
  { href: "/home", label: "Home", icon: "home" },
  {
    label: "Settings",
    icon: "settings",
    items: [{ href: "/settings/profile", label: "Profile" }],
  },
];

/** Every link in `nav`, groups flattened, in order. */
export const navLinks: NavLink[] = nav.flatMap((entry) =>
  "items" in entry ? entry.items : [entry],
);

import type { NextConfig } from "next";

const nextConfig: NextConfig = {
  experimental: {
    // Without this, a server component that imports from the package root
    // ships about 110 kB of extra JavaScript on every route.
    optimizePackageImports: ["@once-ui-system/core"],
  },
};

export default nextConfig;

{
  "Background.gradient.width": {
    "rule": "Quarter-percent units: 400 = 100% of container. Soft glows use width 100–200, not 500.",
    "inRules": true,
    "components": ["Background"]
  },
  "Background.gradient.x": {
    "rule": "x/y are percent positions of the container (50/50 = center).",
    "components": ["Background"]
  },
  "Background.absolute": {
    "rule": "Every absolute decorative layer needs top=\"0\" left=\"0\" or it offsets by parent padding.",
    "inRules": true,
    "components": ["Background", "MatrixFx", "BlobFx"]
  },
  "Card.interactive": {
    "rule": "Card is for interactive surfaces only (href or onClick). Static panels use Column + background=\"surface\" border radius=\"l\".",
    "inRules": true,
    "components": ["Card"]
  },
  "Fade.edge": {
    "rule": "Fade is an edge overlay strip on scroll containers, not a content wrapper.",
    "inRules": true,
    "components": ["Fade"]
  },
  "RevealFx.delay": {
    "rule": "Time is milliseconds everywhere in 3.0: RevealFx (duration, delay), ShineFx and CountFx (duration), TypeFx (charDuration, delay, hold), CelebrationFx and WeatherFx (duration — 5000, not 5), MatrixFx bulge.duration, FlipFx autoFlipInterval, Animation and HoverCard (delay, duration; HoverCard placement=\"cover\" also hideDelay) and Skeleton (delay). Stagger with delay={index * 100}, never index * 0.1 (that was 1.8.x; 0.1 is a tenth of a millisecond, i.e. no stagger). speed is only a multiplier (1 the default, 0.5 half) or \"slow\"/\"medium\"/\"fast\" (0.5/1/2), on MatrixFx, WeatherFx, ParticleFx, CelebrationFx, Effect, Scroller auto, GlitchFx and LetterFx; RevealFx/ShineFx/CountFx speed is duration and TypeFx speed is charDuration since 3.0.",
    "inRules": true,
    "components": [
      "RevealFx",
      "ShineFx",
      "CountFx",
      "TypeFx",
      "CelebrationFx",
      "WeatherFx",
      "MatrixFx",
      "FlipFx",
      "Animation",
      "HoverCard",
      "Skeleton"
    ]
  },
  "RevealFx.translateY": {
    "rule": "translateY as a number is on the token scale: translateY={16} is the token \"16\" (1rem). Use a token such as \"16\"; translateY=\"1rem\" also works.",
    "inRules": true,
    "components": ["RevealFx"]
  },
  "LogoCloud.columns": {
    "rule": "LogoCloud extends Grid — always set columns and responsive overrides or logos stack in one column.",
    "inRules": true,
    "components": ["LogoCloud"]
  },
  "StatusIndicator.scheme": {
    "rule": "StatusIndicator takes scheme=\"green\" | \"red\" | \"orange\" | \"sand\" etc., a fixed palette hue, or tone=\"success\" | \"danger\" | \"brand\" etc., a theme role that follows the theme; not color, its 2.x name, and not variant. Avatar's statusIndicator is { scheme } or { tone }.",
    "components": ["StatusIndicator"]
  },
  "Icon.names": {
    "rule": "Icon names must come from iconNames in catalog.json (spec.json has the same list), and IconName is a real union in 2.0 (an unregistered name is a type error, not a blank space). Do not guess a plausible name, and do not cast one with `as IconName` to silence the check. Brand marks are not in the set — an app registers those itself by augmenting IconLibraryOverrides.",
    "inRules": true,
    "components": ["Icon", "Button", "IconButton"]
  },
  "Icon.cast": {
    "rule": "Never cast an icon name with `as IconName`: the cast compiles a name the registry does not have, and it renders nothing. Use a name from iconNames; in data, type the field as IconName ({ icon: IconName }[]) or write the literal `as const`, so the type check still runs.",
    "components": ["Icon", "IconButton", "Button"]
  },
  "LayoutProvider.next": {
    "rule": "In a Next.js app, import LayoutProvider from \"@once-ui-system/core/next\", not the package root. The root export installs the plain DOM adapters, so SmartLink, Button/Card/ToggleButton with href, Media, Logo, MegaMenu and Kbar render a plain <a> and <img>: no client-side navigation, no next/image, and no error to say so. An app that composes NextAdapterProvider (or AdapterProvider with nextAdapters) itself is already covered.",
    "inRules": true,
    "components": ["LayoutProvider", "SmartLink", "Media", "Button", "Card"]
  },
  "Toast.stable": {
    "rule": "Fixed in 2.1: useToast()'s addToast and removeToast keep one identity for the provider's lifetime, so list addToast in an effect's dependencies like any stable callback. Do not hold it in a ref, or leave it out of the deps, to stop the effect re-running when a toast appears. addToast returns the toast's id for removeToast(id); duration is in milliseconds (default 6000, Infinity until closed).",
    "components": ["Toast", "ToastProvider"]
  },
  "NumberInput.value": {
    "rule": "Fixed in 2.1: NumberInput follows its value prop after mount (an undo, a reset, a change made elsewhere) without rewriting what the user is typing. Pass value and onValueChange; do not remount it with a key to push a new value in.",
    "components": ["NumberInput"]
  },
  "field.size": {
    "rule": "Field heights run a step above Button's: Input size xs is 40px, s 48px, m 56px (the default). A field beside a size=\"s\" Button (32px), as in a toolbar or filter row, takes size=\"xxs\", which is 32px too; Form size=\"xxs\" sets it for every field inside. An xxs field has no floating label: label shows as the placeholder, so keep label for the accessible name.",
    "components": [
      "Input",
      "Select",
      "Textarea",
      "NumberInput",
      "DateInput",
      "ColorInput",
      "TagInput",
      "Form"
    ]
  },
  "Select.closed": {
    "rule": "Fixed in 2.1: Select closes on pick and stays closed — focus returning to the field no longer reopens it — and a multiple Select stays open while picking. Use Select with value and onValueChange; do not build a local picker from Dropdown and Options to get this.",
    "components": ["Select"]
  },
  "Button.trigger": {
    "rule": "Fixed in 2.1: a Button or IconButton that is a Dropdown trigger renders a real <button type=\"button\"> with aria-haspopup and aria-expanded, so it is reachable by keyboard. Pass it as trigger as is; do not add type=\"button\" or a no-op onClick, or wrap it in a focusable Row, to make it one.",
    "components": ["Button", "IconButton", "Dropdown"]
  },
  "Dropdown.contents": {
    "rule": "Fixed in 2.1: a context menu is <Dropdown openOn=\"contextmenu\" trigger={region}>{options}</Dropdown> (2.x ContextMenu): a real menu (menu and menuitem roles, arrow keys, Home/End, Escape returns focus) that opens at the pointer and stays on screen. The trigger region gets a box; set contents to render none (display: contents), so an absolutely positioned or grid/flex child keeps its own layout. Use it instead of a hand-made right-click menu.",
    "components": ["Dropdown"]
  },
  "Tag.duplicate": {
    "rule": "Pass a Tag's text once, as label or as children — with both, the children are dropped. Badge and Chip are Tag in 3.0.",
    "components": ["Tag"]
  },
  "Timeline.notScrubber": {
    "rule": "Timeline lays a sequence of steps down the page. For a video or audio editor's timeline — a playhead over stacked tracks of movable, trimmable blocks — use Scrubber. Do not build one out of Flex and absolute positioning.",
    "components": ["Timeline", "Scrubber"]
  },
  "color.tokens": {
    "rule": "Colors are semantic tokens ({tone}-{weight}), never hex/rgb. background also accepts surface | overlay | page | transparent.",
    "inRules": true,
    "components": ["Column", "Row", "Text", "Button"]
  },
  "color.svgPaint": {
    "rule": "Inline SVG paint is not a hex or rgb literal either: write fill or stroke as currentColor and set the colour with onBackground on the wrapper, or name a token as var(--brand-solid-strong). A literal never follows the theme.",
    "inRules": true,
    "components": ["Icon", "Row", "Column"]
  },
  "color.background-weak": {
    "rule": "*-background-weak is nearly the page color — invisible as accent. Use alpha tokens (brand-alpha-medium) for glows.",
    "inRules": true,
    "components": ["Background"]
  },
  "api.renamed": {
    "rule": "Write 2.x prop names, not 1.x ones from memory: open (not isOpen), checked (not isChecked), SegmentedControl value/onValueChange/defaultValue (not selected/onToggle/defaultSelected), Tag tone (not scheme or variant), Button tone=\"danger\" (not variant=\"danger\"), Text/Heading textVariant (not variant), field size/prefix/suffix/corners (not height/hasPrefix/hasSuffix/radius). The validator names the 2.x prop.",
    "components": [
      "SegmentedControl",
      "Dialog",
      "Checkbox",
      "Switch",
      "Tag",
      "Input",
      "Select",
      "Button"
    ]
  },
  "layout.shorthands": {
    "rule": "Use fill not fillWidth fillHeight; center not horizontal=\"center\" vertical=\"center\"; Row/Column not Flex direction=, and Row for a Flex with no direction (Flex defaults to row). Flex is for a direction that changes at a breakpoint.",
    "inRules": true,
    "components": ["Row", "Column", "Flex", "Grid"]
  },
  "theme.typedProps": {
    "rule": "Theme a subtree with the typed props theme, themeBorder, themeSolid and themeSurface — on Flex, Row, Column, Grid and every component built on them (Background, Tag, the effects) — not raw data-theme, data-border, data-solid or data-surface. Keep the raw attribute only where no prop exists: data-border=\"rounded\" on Button and IconButton, data-brand anywhere.",
    "inRules": true,
    "components": ["Row", "Column", "Flex", "Grid", "Background"]
  },
  "layout.defaults": {
    "rule": "Never write props equal to defaults or implied by another prop on the element: position=\"relative\", direction on Row/Column, variant=\"primary\" on Button, fillWidth beside maxWidth (maxWidth already fills the width), minWidth={0} beside fillWidth (fillWidth already sets min-width: 0).",
    "inRules": true,
    "components": ["Row", "Column", "Grid", "Button"]
  },
  "Logo.themes": {
    "rule": "A logo that changes with the theme is one Logo with a source per theme: <Logo wordmark={{ light: \"/logo-light.svg\", dark: \"/logo-dark.svg\" }} /> (icon takes the same pair). Do not render two Logos with showIn=\"dark\" and showIn=\"light\": twice the elements, two places to keep in sync, and a hidden link in the focus order. Keep showIn for a logo that should only appear in one theme.",
    "inRules": true,
    "components": ["Logo"]
  },
  "Logo.text": {
    "rule": "wordmark is an image source. For a name set in type, use <Logo icon=\"/mark.svg\" text=\"Acme\" />.",
    "components": ["Logo"]
  },
  "Tag.inline": {
    "rule": "Tag is a div by default; inside a sentence (<Text as=\"p\">, <p>) give it as=\"span\".",
    "components": ["Tag"]
  },
  "border.default": {
    "rule": "Bare border (and borderTop, borderBottom, borderX, …) draws the default border: --default-border, neutral-alpha-weak unless the app sets it in its custom CSS. Do not write border=\"neutral-alpha-weak\" to get it, which pins the colour; name a colour only to deviate, e.g. border=\"neutral-alpha-medium\" or border=\"brand-alpha-medium\".",
    "inRules": true,
    "components": ["Row", "Column", "Card"]
  },
  "zIndex.scope": {
    "rule": "zIndex is for an isolated stacking group: an absolute decorative layer and its content sibling (zIndex={1}), or a sticky header over its pane. Never on a lone element, never a page-wide ladder of 3 / 5 / 9 — restructure the tree instead.",
    "inRules": true,
    "components": ["Row", "Column", "Background"]
  },
  "section.gaps": {
    "rule": "Gap between page sections: 80–160 (typical 104). Inside sections: 24–40.",
    "inRules": true,
    "components": ["Column"]
  },
  "heading.scale": {
    "rule": "Hero = display-strong-l/xl; section titles = display-strong-xs/s — never heading-* for section titles.",
    "inRules": true,
    "components": ["Heading"]
  },
  "animation.budget": {
    "rule": "Entry animation budget: hero + at most 1–2 key moments. Animate coherent blocks all-or-none within a sibling set.",
    "inRules": true,
    "components": ["RevealFx", "CountFx"]
  },
  "CountFx.trigger": {
    "rule": "CountFx has no trigger prop — drive value from useInViewport latch instead.",
    "inRules": true,
    "components": ["CountFx"]
  },
  "overflow.hero": {
    "rule": "overflow=\"hidden\" on full-bleed sections clips glows into hard bands — only use when parent has radius.",
    "components": ["Column", "Background"]
  },
  "layout.responsiveProps": {
    "rule": "Responsive xl/l/m/s/xs props exist only on Flex, Row, Column and Grid; Text and Heading take just s={{ hide: true }}. Button and the rest have none: to change one at a breakpoint, wrap it in a Row or Column and put the breakpoint prop there. Text and Heading take padding and flex but no radius or border; put those on the wrapper.",
    "inRules": true,
    "components": ["Flex", "Row", "Column", "Grid", "Button", "Text"]
  },
  "layout.leafProps": {
    "rule": "Leaf components (Button, IconButton, ToggleButton, the fields, Switch, Checkbox, RadioButton, Text, Heading, Icon, Avatar, Spinner, StatusIndicator, Kbd, InlineCode, ProgressBar, Logo, SmartLink, NavIcon) take only margins, flex, fillWidth, position, top/right/bottom/left, className and style besides their own props. Padding, background, border, radius, sizes, hide and breakpoints go on a Row around it (a Column around Text or Heading; <Row fit> for an Icon's box).",
    "components": ["Button", "Text", "Heading", "Icon", "Input", "Row", "Column"]
  },
  "layout.noBaseline": {
    "rule": "vertical and horizontal take start, center, end, between, around, even or stretch. There is no baseline; for baseline-aligned text use style={{ alignItems: \"baseline\" }}.",
    "inRules": true,
    "components": ["Flex", "Row", "Column"]
  },
  "spacing.tokens": {
    "rule": "gap, padding and margin take spacing tokens (\"0\", \"1\", \"2\", \"4\", \"8\", \"12\", \"16\", \"20\", \"24\", \"32\", \"40\", \"48\", \"56\", \"64\", \"72\", \"80\", \"104\", \"128\", \"160\", or xs–xl). \"6\" and \"10\" are not tokens and are type errors.",
    "inRules": true,
    "components": ["Flex", "Row", "Column", "Grid"]
  },
  "layout.noSpanOrType": {
    "rule": "Row, Column and Grid have no span and no type prop. A clickable row is a Button (or a native <button>), and a Grid child spanning columns uses style={{ gridColumn: \"span 2\" }}.",
    "inRules": true,
    "components": ["Row", "Column", "Grid"]
  },
  "Checkbox.checked": {
    "rule": "Checkbox, Switch and RadioButton take checked (or defaultChecked) and onCheckedChange(checked: boolean); onChange is the native event of their input. onToggle was 2.x; isChecked and isIndeterminate were 1.x.",
    "inRules": true,
    "components": ["Checkbox", "Switch", "RadioButton"]
  },
  "RevealFx.primaryContent": {
    "rule": "Never wrap primary content (headlines, prices, KPIs, CTAs) in RevealFx: it stays blurred and unreadable until the reveal ends. Reveal secondary sections only, with duration={1000}.",
    "inRules": true,
    "components": ["RevealFx"]
  },
  "size.rem": {
    "rule": "A number on any size, spacing or offset prop is on the token scale in 3.0 (it was rem in 2.x): width={32} renders as width=\"32\" (2rem, 32 px at the defaults, scaled by data-scaling), maxWidth={40} is 2.5rem. For 40rem write the string, maxWidth=\"40rem\". An icon or avatar box is usually \"24\" to \"48\", or 24 to 48 as numbers.",
    "inRules": true,
    "components": ["Flex", "Row", "Column", "Grid"]
  },
  "Chart.xAxis": {
    "rule": "The x axis reads the first key of data[0] that is not a series key (date, label, month). Put that key first in every point and list only the plotted keys in series: series={[{ key: \"visitors\" }]} with data={[{ date: \"Oct 1\", visitors: 1840 }]}.",
    "components": ["LineChart", "BarChart", "LineBarChart"]
  },
  "Map.positions": {
    "rule": "Positions are [longitude, latitude], not [lat, lng]. Map needs a height (or fill inside a sized parent); it shadows the global Map, so import it as another name in a file that also uses new Map().",
    "components": ["Map", "MapMarker", "MapMarkers", "MapPopup", "MapCircle"]
  }
}

"use client";

/**
 * The three shells from `ai/layouts.md`, as code that compiles.
 *
 * A recipe nobody ever ran is a suggestion. These live here so `pnpm typecheck`
 * covers them: if a prop is renamed or a component changes shape, the recipe
 * fails with everything else rather than going quietly stale in a markdown file.
 *
 * Read `ai/layouts.md` for what each decision is for — the scrolling pane, the
 * sticky offset, the mobile drawer, why nav selection needs the longest match
 * rather than an equality check.
 */
import type { IconName } from "@once-ui-system/core";
import {
  Column,
  Drawer,
  IconButton,
  Nav,
  NavGroup,
  NavItem,
  Row,
  SplitView,
  selectNavHref,
} from "@once-ui-system/core";
import { Scrubber } from "@once-ui-system/core/media";
import { useState } from "react";

export const Shell = ({
  children,
  nav,
  pathname,
}: {
  children: React.ReactNode;
  nav: Item[];
  pathname: string;
}) => {
  // The drawer is open for the path it was opened on, so following one of its
  // links closes it with the navigation — no effect watching the pathname.
  const [menuPath, setMenuPath] = useState<string | null>(null);
  const menuOpen = menuPath === pathname;

  return (
    <Column fill horizontal="center" flex={1}>
      <Row height="56" fillWidth vertical="center" paddingX="16" gap="8">
        <Row hide s={{ hide: false }}>
          <IconButton
            icon="moreHorizontal"
            variant="tertiary"
            tooltip="Menu"
            aria-expanded={menuOpen}
            onClick={() => setMenuPath(pathname)}
          />
        </Row>
        {/* logo, search, account */}
      </Row>
      <Row fill paddingX="8">
        <Column s={{ hide: true }} maxWidth="18rem" fitHeight position="sticky" top="56">
          <SideNav nav={nav} pathname={pathname} />
        </Column>
        <Row fill horizontal="center" topRadius="l" overflow="hidden">
          <Row
            height="below-header"
            overflowY="auto"
            topRadius="l"
            horizontal="center"
            fillWidth
            background="surface"
          >
            <Column maxWidth="xl" gap="m" paddingY="32" fitHeight>
              {children}
            </Column>
          </Row>
        </Row>
      </Row>
      <Drawer
        open={menuOpen}
        onClose={() => setMenuPath(null)}
        side="left"
        size="s"
        title="Menu"
        flush
      >
        <Column paddingTop="64" paddingBottom="16">
          <SideNav nav={nav} pathname={pathname} />
        </Column>
      </Drawer>
    </Column>
  );
};

type Sub = { href: string; label: string; badge?: number };
type Item = { key: string; label: string; icon?: IconName; href?: string; items?: Sub[] };

export const SideNav = ({ nav, pathname }: { nav: Item[]; pathname: string }) => {
  const current = selectNavHref(
    pathname,
    nav.flatMap((i) => (i.items ? i.items.map((s) => s.href) : [i.href!])),
  );
  return (
    <Nav fill paddingX="8" aria-label="Main">
      {nav.map((item) =>
        item.items ? (
          <NavGroup
            key={item.key}
            label={item.label}
            icon={item.icon}
            defaultOpen={item.items.some((s) => s.href === current)}
          >
            {item.items.map((sub) => (
              <NavItem
                key={sub.href}
                href={sub.href}
                label={sub.label}
                badge={sub.badge}
                selected={sub.href === current}
              />
            ))}
          </NavGroup>
        ) : (
          <NavItem
            key={item.href}
            href={item.href}
            icon={item.icon}
            label={item.label}
            selected={item.href === current}
          />
        ),
      )}
    </Nav>
  );
};

export const Editor = ({
  duration,
  time,
  setTime,
  tracks,
  pause,
}: {
  duration: number;
  time: number;
  setTime: (t: number) => void;
  tracks: React.ComponentProps<typeof Scrubber>["tracks"];
  pause: () => void;
}) => (
  <Column fill>
    <SplitView
      fill
      leftPanel={<Column fill overflowY="auto" />}
      rightPanel={<Column fill overflowY="auto" />}
      defaultSplit={0.28}
      minSplit={0.2}
      maxSplit={0.6}
      collapseBelow="s"
      labels={{ left: "Layers", right: "Canvas" }}
    />
    <Scrubber
      duration={duration}
      value={time}
      onValueChange={setTime}
      tracks={tracks}
      onGestureStart={pause}
    />
  </Column>
);

"use client";

/**
 * Gold example: list page
 * Target: a page of records — title with the one primary action, a status
 * filter, a searchable, sortable, paginated Table with status tags and row
 * actions, and an empty state that offers a way back.
 *
 * Table searches and sorts by the text inside each cell, so a cell that is a
 * component (the name with its email, the status Tag) should carry its text as
 * children, not only in a prop.
 */
import {
  Button,
  Column,
  Heading,
  Row,
  SegmentedControl,
  Table,
  Tag,
  Text,
} from "@once-ui-system/core";
import { useState } from "react";

type Status = "active" | "invited" | "suspended";

type Member = {
  name: string;
  email: string;
  role: string;
  status: Status;
  lastActive: string;
};

const members: Member[] = [
  {
    name: "Ada Park",
    email: "ada@acme.dev",
    role: "Owner",
    status: "active",
    lastActive: "2026-10-09",
  },
  {
    name: "Bruno Silva",
    email: "bruno@acme.dev",
    role: "Admin",
    status: "active",
    lastActive: "2026-10-08",
  },
  { name: "Chen Wei", email: "chen@acme.dev", role: "Editor", status: "invited", lastActive: "—" },
  {
    name: "Dara Okafor",
    email: "dara@acme.dev",
    role: "Viewer",
    status: "suspended",
    lastActive: "2026-08-21",
  },
];

// The scheme colours the tag and the text says the same thing, so status is
// never carried by colour alone.
const statusTag: Record<Status, { scheme: "success" | "warning" | "danger"; label: string }> = {
  active: { scheme: "success", label: "Active" },
  invited: { scheme: "warning", label: "Invited" },
  suspended: { scheme: "danger", label: "Suspended" },
};

type Filter = "all" | Status;

export function ListPageExample({
  onInvite,
  onEdit,
  onRemove,
}: {
  onInvite?: () => void;
  onEdit?: (member: Member) => void;
  onRemove?: (member: Member) => void;
}) {
  const [filter, setFilter] = useState<Filter>("all");
  const visible = members.filter((member) => filter === "all" || member.status === filter);

  return (
    <Column as="main" fillWidth horizontal="center" paddingY="48" paddingX="24">
      <Column maxWidth="l" gap="24">
        <Row
          fillWidth
          horizontal="between"
          vertical="end"
          gap="16"
          s={{ direction: "column", horizontal: "start" }}
        >
          <Column gap="8">
            <Heading as="h1" textVariant="display-strong-xs">
              Members
            </Heading>
            <Text textVariant="body-default-s" onBackground="neutral-weak">
              Everyone with access to this workspace.
            </Text>
          </Column>
          <Button prefixIcon="plus" onClick={onInvite}>
            Invite member
          </Button>
        </Row>

        <SegmentedControl
          fillWidth={false}
          value={filter}
          onValueChange={(value) => setFilter(value as Filter)}
          buttons={[
            { value: "all", label: "All" },
            { value: "active", label: "Active" },
            { value: "invited", label: "Invited" },
            { value: "suspended", label: "Suspended" },
          ]}
        />

        <Table
          searchable
          searchPlaceholder="Search members"
          paginated
          defaultPerPage={10}
          emptyState={
            <Column center gap="12" padding="32">
              <Text textVariant="body-default-s" onBackground="neutral-weak">
                No members match this filter.
              </Text>
              <Button size="s" variant="secondary" onClick={() => setFilter("all")}>
                Show everyone
              </Button>
            </Column>
          }
          columns={[
            { header: "Name", key: "name", sortable: true },
            { header: "Role", key: "role", sortable: true },
            { header: "Status", key: "status", sortable: true },
            { header: "Last active", key: "lastActive", sortable: true, align: "right" },
          ]}
          rows={visible.map((member) => [
            <Column key="name" gap="4">
              <Text textVariant="label-default-s">{member.name}</Text>
              <Text textVariant="body-default-xs" onBackground="neutral-weak">
                {member.email}
              </Text>
            </Column>,
            member.role,
            <Tag key="status" size="s" tone={statusTag[member.status].scheme}>
              {statusTag[member.status].label}
            </Tag>,
            member.lastActive,
          ])}
          perPageOptions={[5, 10, 20, 50]}
          showFirstLast
          actions={[
            {
              icon: "edit",
              tooltip: "Edit member",
              onClick: (_row, index) => onEdit?.(visible[index]),
            },
            {
              icon: "trash",
              tooltip: "Remove member",
              variant: "primary",
              tone: "danger",
              onClick: (_row, index) => onRemove?.(visible[index]),
            },
          ]}
        />
      </Column>
    </Column>
  );
}

